package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitable;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.jsonschema.SchemaAware;
import com.fasterxml.jackson.databind.jsontype.TypeSerializer;
import com.fasterxml.jackson.databind.node.JsonNodeFactory;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.ser.JsonSerializer;
import com.fasterxml.jackson.databind.ser.ResolvableSerializer;
import com.fasterxml.jackson.databind.ser.std.StdDelegatingSerializer;
import com.fasterxml.jackson.databind.util.Converter;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.lang.reflect.ReflectPermission;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

/**
 * Unit tests for StdDelegatingSerializer#getSchema
 */
public class StdDelegatingSerializer_getSchema_TriageGen2Test {

    private SerializerProvider mockProvider;
    private Type mockTypeHint;

    // Interface to simulate SchemaAware for testing
    public interface SchemaAware {
        JsonNode getSchema(SerializerProvider provider, Type typeHint) throws JsonMappingException;
    }

    // Concrete implementation of StdDelegatingSerializer for testing
    public static class TestDelegatingSerializer extends StdDelegatingSerializer {
        public TestDelegatingSerializer(JsonSerializer<?> delegate) {
            super(delegate);
        }
    }

    // Concrete implementation of a SchemaAware serializer
    public static class SchemaAwareDelegate implements JsonSerializer, SchemaAware {
        private final JsonNode schemaNode;

        public SchemaAwareDelegate(JsonNode schemaNode) {
            this.schemaNode = schemaNode;
        }

        @Override
        public void serialize(Object value, JsonGenerator gen, SerializerProvider provider) {
            // Not used in getSchema test
        }

        @Override
        public JsonNode getSchema(SerializerProvider provider, Type typeHint) throws JsonMappingException {
            return schemaNode;
        }
    }

    // Regular serializer that does NOT implement SchemaAware
    public static class RegularDelegate implements JsonSerializer {
        @Override
        public void serialize(Object value, JsonGenerator gen, SerializerProvider provider) {
            // Not used
        }
    }

    @Before
    public void setUp() {
        mockProvider = mock(SerializerProvider.class);
        mockTypeHint = mock(Type.class);
    }

    /**
     * Tests the branch where the delegate IS an instance of SchemaAware.
     * It should call the delegate's getSchema method.
     */
    @Test
    public void testGetSchema_WithSchemaAwareDelegate() throws JsonMappingException, NoSuchFieldException, IllegalAccessException {
        ObjectNode expectedSchema = JsonNodeFactory.instance.objectNode().put("property", "value");
        SchemaAwareDelegate delegate = new SchemaAwareDelegate(expectedSchema);
        TestDelegatingSerializer serializer = new TestDelegatingSerializer(delegate);

        JsonNode result = serializer.getSchema(mockProvider, mockTypeHint);

        assertEquals(expectedSchema, result);
    }

    /**
     * Tests the branch where the delegate is NOT an instance of SchemaAware.
     * It should fallback to super.getSchema (which returns null in StdSerializer/StdDelegatingSerializer).
     */
    @Test
    public void testGetSchema_WithRegularDelegate() throws JsonMappingException {
        RegularDelegate delegate = new RegularDelegate();
        TestDelegatingSerializer serializer = new TestDelegatingSerializer(delegate);

        // super.getSchema typically returns null for standard serializers
        JsonNode result = serializer.getSchema(mockProvider, mockTypeHint);

        assertEquals(null, result);
    }

    /**
     * Tests the branch where the delegate is null.
     * This handles the edge case of nullity and ensures it falls back to super.
     */
    @Test
    public void testGetSchema_WithNullDelegate() throws JsonMappingException {
        TestDelegatingSerializer serializer = new TestDelegatingSerializer(null);

        JsonNode result = serializer.getSchema(mockProvider, mockTypeHint);

        assertEquals(null, result);
    }

    /**
     * Tests that JsonMappingException is propagated correctly if the delegate throws it.
     */
    @Test(expected = JsonMappingException.class)
    public void testGetSchema_ThrowsException() throws JsonMappingException {
        SchemaAware throwingDelegate = new SchemaAware() {
            @Override
            public JsonNode getSchema(SerializerProvider provider, Type typeHint) throws JsonMappingException {
                throw new JsonMappingException(null, "Simulated error");
            }

            @Override
            public void serialize(Object value, JsonGenerator gen, SerializerProvider provider) {}
        };

        TestDelegatingSerializer serializer = new TestDelegatingSerializer(throwingDelegate);
        serializer.getSchema(mockProvider, mockTypeHint);
    }
}
